CREATE TABLE deployment_environments (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, name TEXT NOT NULL, display_name TEXT NOT NULL, provider TEXT NOT NULL, remote_identifier TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,name));
CREATE TABLE deployment_bindings (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, environment_id TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE release_candidates (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, delivery_candidate_id TEXT NOT NULL, snapshot_id TEXT NOT NULL UNIQUE, version INTEGER NOT NULL, target_sha TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,version));
CREATE TABLE release_snapshots (id TEXT PRIMARY KEY, release_candidate_id TEXT NOT NULL UNIQUE, version INTEGER NOT NULL, target_sha TEXT NOT NULL, artifacts_hash TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TRIGGER release_snapshot_immutable_update BEFORE UPDATE ON release_snapshots BEGIN SELECT RAISE(ABORT,'Release snapshots are immutable'); END;
CREATE TRIGGER release_snapshot_immutable_delete BEFORE DELETE ON release_snapshots BEGIN SELECT RAISE(ABORT,'Release snapshots are immutable'); END;
CREATE TABLE deployment_runs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, release_candidate_id TEXT NOT NULL, environment_id TEXT NOT NULL, target_sha TEXT NOT NULL, status TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE deployment_attempts (id TEXT PRIMARY KEY, deployment_run_id TEXT NOT NULL, attempt_number INTEGER NOT NULL, data TEXT NOT NULL, UNIQUE(deployment_run_id,attempt_number));
CREATE TABLE deployment_leases (id TEXT PRIMARY KEY, environment_id TEXT NOT NULL, lease_token TEXT NOT NULL UNIQUE, held_by_run_id TEXT NOT NULL, status TEXT NOT NULL, expires_at TEXT NOT NULL, acquired_at TEXT NOT NULL, released_at TEXT);
CREATE UNIQUE INDEX deployment_active_lease ON deployment_leases(environment_id) WHERE status='active';
CREATE TABLE deployment_operations (id TEXT PRIMARY KEY, deployment_run_id TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, operation_type TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE deployment_records (id TEXT PRIMARY KEY, deployment_run_id TEXT NOT NULL, kind TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX deployment_records_lookup ON deployment_records(deployment_run_id,kind);
CREATE TABLE deployment_approvals (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, release_candidate_id TEXT NOT NULL, environment_id TEXT NOT NULL, action TEXT NOT NULL, status TEXT NOT NULL, actor_id TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE deployment_phase_telemetry (id TEXT PRIMARY KEY, deployment_run_id TEXT NOT NULL, phase_name TEXT NOT NULL, duration_ms INTEGER, queue_wait_ms INTEGER, human_wait_ms INTEGER, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL);
CREATE TABLE deployment_internal_steps (id TEXT PRIMARY KEY, deployment_run_id TEXT NOT NULL, step_name TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT, metadata TEXT NOT NULL);
CREATE TABLE deployment_promotions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, release_candidate_id TEXT NOT NULL, from_environment_id TEXT NOT NULL, to_environment_id TEXT NOT NULL, target_sha TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE deployment_logs (id TEXT PRIMARY KEY, deployment_run_id TEXT NOT NULL, attempt_number INTEGER NOT NULL, log_level TEXT NOT NULL, message_sanitized TEXT NOT NULL, source TEXT NOT NULL, timestamp TEXT NOT NULL);
CREATE TABLE deployment_incidents (id TEXT PRIMARY KEY, deployment_run_id TEXT NOT NULL, environment_id TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, suggested_action TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE health_check_profiles (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, environment_id TEXT NOT NULL, name TEXT NOT NULL, check_type TEXT NOT NULL, target TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE health_check_results (id TEXT PRIMARY KEY, deployment_run_id TEXT NOT NULL, profile_id TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL, checked_at TEXT NOT NULL);
CREATE TABLE deployment_rollback_plans (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, deployment_run_id TEXT NOT NULL, environment_id TEXT NOT NULL, current_release_id TEXT NOT NULL, target_release_id TEXT NOT NULL, target_sha TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE deployment_rollback_executions (id TEXT PRIMARY KEY, rollback_plan_id TEXT NOT NULL, status TEXT NOT NULL, initiated_by TEXT NOT NULL, data TEXT NOT NULL, executed_at TEXT NOT NULL);
